<div class="right_col" role="main"><div class="d-flex justify-content-between mb-3"><h2>Document Verification</h2><form method="get"><select name="status" class="form-control" onchange="this.form.submit()"><option value="">All statuses</option><?php foreach(['pending','verified','rejected'] as $s): ?><option value="<?= $s ?>" <?= $status===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach ?></select></form></div><div class="card shadow-sm"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Application</th><th>Document</th><th>File</th><th>Status</th><th>Review</th></tr></thead><tbody><?php foreach($items as $d): ?><tr><td><?= esc($d->application_no) ?><br><?= esc($d->student_name) ?><br><small><?= esc($d->school_name) ?></small></td><td><?= esc(ucwords(str_replace('_',' ',$d->document_type))) ?><br><small><?= esc($d->original_name) ?></small></td><td><a target="_blank" href="<?= base_url('school/admission/documents/'.$d->id.'/file') ?>">Open document</a></td><td><?= esc(ucfirst($d->verification_status)) ?><?php if($d->verification_note): ?><br><small><?= esc($d->verification_note) ?></small><?php endif ?></td><td><?= form_open('school/admission/documents/'.$d->id.'/review') ?><input class="form-control form-control-sm mb-1" name="note" placeholder="Verification note"><button name="decision" value="verified" class="btn btn-sm btn-success">Verify</button> <button name="decision" value="rejected" class="btn btn-sm btn-danger">Reject</button><?= form_close() ?></td></tr><?php endforeach ?><?php if(!$items): ?><tr><td colspan="5" class="text-center text-muted">No uploaded documents.</td></tr><?php endif ?></tbody></table></div></div></div>
